export type Topic = {
  id: number; title: string; prerequisites: number[]; environment: string;
  objective: string; sections: [string, string][]; example: string; language: string;
  task: string; rubric: string[]; solution: string; mistake: string;
  question: string; options: string[]; answer: number; feedback: string; sources: [string,string][];
};

export const topics: Topic[] = [
  {
    id:1, title:'Your terminal, files, and Git', prerequisites:[], environment:'Local terminal · PowerShell or Bash · Git installed',
    objective:'Navigate a project safely, inspect text, and save a reproducible change with Git.',
    sections:[['Think in paths','A directory is a container; a path locates a file. Relative paths start from your current directory. Absolute paths start from a drive or root. Inspect your location before changing files. Linux permissions separate owner, group, and others; read, write, and execute are distinct rights. Give a service access to its own data rather than making everything writable.'],['Read and compose commands','Bash pwd, ls, cd, cat, and grep correspond to PowerShell Get-Location, Get-ChildItem, Set-Location, Get-Content, and Select-String. A pipe passes output to the next command. Bash commonly passes text; PowerShell often passes objects. Quote paths containing spaces. Environment variables configure a process: $env:APP_ENV in PowerShell and $APP_ENV in Bash. Never print secrets to debug configuration.'],['Git is your change journal','The working tree contains edits; the index stages selected edits; a commit saves a snapshot. Inspect git status and git diff, stage specific files, then commit with a reason. A branch names a sequence of commits. Pull requests let another person review changes. Resolve a conflict by understanding both edits, removing markers, and testing the result. Ignore virtual environments, generated outputs, and secrets; .gitignore does not remove secrets already committed.']],
    language:'PowerShell', example:'Get-Location\nGet-ChildItem\nNew-Item -ItemType Directory -Force practice\nSet-Content practice/notes.txt "grain: one row per order"\nGet-Content practice/notes.txt | Select-String "grain"\ngit status\ngit diff',
    task:'In a new practice directory, create a notes file, find a word in it, initialize a Git repository there, add the file, and commit. Change the note and inspect the diff before making a second commit. Do not initialize inside an existing repository.',
    rubric:['You can explain your current directory and relative file path.','git log shows two commits; git diff showed only the intended line.','No passwords, generated data, or virtual environments were committed.'],
    solution:'Run git init in the new practice directory; git add notes.txt; git commit -m "Document order grain". Edit notes.txt, run git diff, stage and commit again. Use git log --oneline to inspect the history. Git may require your name/email configuration before the first commit.',
    mistake:'Running a destructive command from an unexpected directory. Check the location and preview the exact target first.', question:'What does git add do?',options:['Uploads files to GitHub','Stages changes for the next commit','Deletes old commits'],answer:1,feedback:'Staging selects the changes a commit will include. It does not publish them.',sources:[['Git book','https://git-scm.com/book/en/v2'],['PowerShell overview','https://learn.microsoft.com/en-us/powershell/scripting/overview']]
  },
  {
    id:2,title:'Networking and reliable API ingestion',prerequisites:[1],environment:'Browser + local terminal · no cloud account needed',objective:'Trace a request and design ingestion that survives failures without losing pages.',
    sections:[['Follow one request','DNS translates a hostname to an address. IP routes packets; TCP provides an ordered byte stream with retransmission. A port identifies the listening service, such as your local application on 3007. TLS encrypts traffic and verifies the server identity. HTTP then carries a method, path, headers, and body. Authentication proves who you are; authorization determines what you may access. A load balancer distributes requests to healthy servers; it does not fix bad queries.'],['Interpret failures','A DNS failure happens before HTTP. Connection refusal often means no listener on that address/port. A timeout needs separate connection and response limits. HTTP 401 suggests authentication, 403 permission, 404 missing resource, 429 rate limiting, and 5xx a server failure. Retry transient failures with a bounded attempt count, exponential backoff, and jitter; obey Retry-After. Do not blindly retry non-idempotent writes.'],['Read the whole dataset','APIs may use page numbers, offsets, or cursor tokens. Save the next cursor only after durable storage of the current page. Record request parameters, page count, and ingestion timestamp. Deduplicate by a stable source key. Incremental requests based on updated_at need a small overlap and deduplication to cover late updates. Handle deletes explicitly; absence from one page is not proof of deletion.']],
    language:'PowerShell',example:'Resolve-DnsName example.com\nTest-NetConnection localhost -Port 3007\nInvoke-WebRequest -Uri http://localhost:3007/ -TimeoutSec 10',task:'Draw DNS → TCP → TLS → HTTP for an HTTPS API. Design a three-page ingestion where page 2 gets a 429 once and the process crashes after saving page 2. State what you save and where you restart.',rubric:['Retries are bounded and respect the rate limit.','The cursor advances only after the page is durable.','A restart does not duplicate logical records or skip page 3.'],solution:'Store page data and a checkpoint together where possible. On 429, wait as instructed and retry the same cursor. After a crash, restart from the last committed checkpoint; deduplicate by source key if a page is replayed. Log counts and response status without tokens.',mistake:'Treating all HTTP errors as retryable or logging the Authorization header.',question:'When should a page cursor be committed?',options:['Before fetching the page','After durable storage of that page','After seeing any HTTP response'],answer:1,feedback:'A checkpoint promises the data before it is safe. Advancing too early can skip data after a crash.',sources:[['HTTP overview','https://developer.mozilla.org/en-US/docs/Web/HTTP/Overview'],['HTTP semantics','https://www.rfc-editor.org/rfc/rfc9110']]
  },
  {
    id:3,title:'SQL: from rows to trustworthy answers',prerequisites:[],environment:'Browser SQL · commerce dataset',objective:'Control grain, joins, aggregation, windows, and query plans; use the 32 SQL lessons for deliberate practice.',
    sections:[['Build a query in stages','Start by stating what one result row represents. FROM and JOIN build the row set; WHERE selects rows; GROUP BY and aggregates summarize it; HAVING filters groups; windows calculate across the remaining rows; ORDER BY presents results. This is a reasoning model, not a promise about physical execution. NULL means unknown: use IS NULL and decide whether missing values belong in a denominator. CAST types deliberately; money rounding is a business rule.'],['Prevent misleading joins','If an order joins to three line items, the order amount appears three times. Aggregate each source to the required grain before joining, or aggregate line amounts directly. DISTINCT may hide an error rather than solve it. A LEFT JOIN preserves unmatched left rows, but filtering the right table in WHERE can remove them. Use EXISTS for membership and NOT EXISTS for absence. UNION ALL preserves duplicates; UNION removes them.'],['Use windows and CTEs deliberately','A CTE names an intermediate result so you can inspect it. ROW_NUMBER selects one row per key when the ordering is deterministic; RANK retains ties with gaps; DENSE_RANK retains ties without gaps. LAG compares rows, not necessarily calendar periods. Specify a ROWS frame for row-by-row running totals and decide how ties behave. Inspect EXPLAIN after proving correctness; indexes, partitions, and column pruning depend on the engine. Transactions make several changes succeed or fail as a unit; browser exercises here focus on reads.']],
    language:'DuckDB SQL',example:'WITH spend AS (\n  SELECT customer_id, SUM(amount) AS revenue\n  FROM orders GROUP BY customer_id\n)\nSELECT c.customer_id, c.name, COALESCE(s.revenue, 0) AS revenue\nFROM customers c LEFT JOIN spend s USING (customer_id)\nORDER BY revenue DESC, c.customer_id;',task:'Run the example on commerce. Explain why customers without orders remain. Then rank customers within each city by lifetime_value using DENSE_RANK. Use SQL Studio below for the detailed lessons and related challenges.',rubric:['One output row per customer is maintained.','Unmatched customers have zero revenue only because that reporting rule was chosen.','Ranking partitions by city and orders by lifetime_value descending.'],solution:'SELECT customer_id, city, lifetime_value, DENSE_RANK() OVER (PARTITION BY city ORDER BY lifetime_value DESC) AS value_rank FROM customers ORDER BY city, value_rank, customer_id; Add customer_id to presentation ordering, not the rank ordering, to preserve equal-value ties.',mistake:'Summing an order-level amount after joining to a finer-grained table.',question:'Two orders join to three line items each. What happens to SUM(order_amount)?',options:['It remains unchanged','It can be multiplied by three','SQL automatically deduplicates orders'],answer:1,feedback:'The joined row set repeats each amount. Fix the grain before calculating the metric.',sources:[['DuckDB SQL','https://duckdb.org/docs/stable/sql/introduction'],['PostgreSQL tutorial','https://www.postgresql.org/docs/current/tutorial.html']]
  },
  {
    id:4,title:'Python, pandas, and NumPy for data',prerequisites:[1,3],environment:'Local Python 3 · pandas and NumPy in a virtual environment',objective:'Write a small tested transformation, then apply tabular and array operations without hiding bad data.',
    sections:[['Start with plain Python','A list holds ordered values; a dictionary maps keys to values. Loops iterate; functions isolate a transformation; return produces a result. Keep input/output separate from transformation logic so a test can call the function directly. Use explicit types when reading CSV because CSV stores text. Catch expected exceptions such as ValueError; do not silently catch every exception and report success. Use pathlib for paths and with to close files.'],['Create a reproducible environment','In PowerShell, run py -3 -m venv .venv, then .venv\\Scripts\\python -m pip install pandas numpy. Run scripts with that interpreter without needing an activation policy change. Record the tested dependencies. Set configuration through arguments or environment variables; keep tokens out of source. Add a simple assertion test before connecting real inputs. Large files may require chunks or a warehouse instead of loading everything into memory.'],['Move to columns','pandas DataFrames have labeled columns; filter with a boolean mask, groupby for aggregation, and merge with validate to detect unexpected join cardinality. NumPy arrays support vectorized numerical operations and broadcasting: operations apply to compatible shapes, not Python lists of arbitrary objects. Missing values and dtypes affect arithmetic. Prefer column operations to row loops, but inspect row counts and nulls after every transformation.']],
    language:'Python',example:'def total_paid(rows):\n    return sum(int(r["amount"]) for r in rows if r["status"] == "paid")\n\nrows = [{"amount": "20", "status": "paid"},\n        {"amount": "7", "status": "cancelled"}]\nassert total_paid(rows) == 20\n\nimport pandas as pd\nimport numpy as np\ndf = pd.DataFrame(rows)\ndf["amount"] = pd.to_numeric(df["amount"], errors="raise")\nprint(df.loc[df["status"].eq("paid"), "amount"].sum())\nprint(np.array([20, 30]) * 2)',task:'Run this as a local file. Add a second paid row of 30 and assert the total is 50. Add a malformed amount and decide whether to reject it or quarantine the row. Group paid rows by a new city column in pandas.',rubric:['The plain function and pandas calculation agree.','Malformed numeric input raises an error or is recorded in a reject output.','Cancelled orders do not enter paid revenue; NumPy output is [40, 60].'],solution:'Filter paid rows, convert amount explicitly, and use df.loc[df.status.eq("paid")].groupby("city")["amount"].sum(). Test empty input, a cancelled row, and a malformed paid amount. errors="coerce" needs a separate null/reject check; otherwise it can hide lost revenue.',mistake:'Using errors="coerce" and summing without checking how many records became missing.',question:'Why keep transformation functions separate from file reading?',options:['It makes every pipeline faster','They can be tested with small inputs independently','Python requires this layout'],answer:1,feedback:'Small deterministic functions let you test correctness without a filesystem or API.',sources:[['Python tutorial','https://docs.python.org/3/tutorial/'],['pandas getting started','https://pandas.pydata.org/docs/getting_started/intro_tutorials/'],['NumPy fundamentals','https://numpy.org/doc/stable/user/basics.html']]
  },
  {
    id:5,title:'Data modeling: grain, keys, and history',prerequisites:[3],environment:'Browser SQL + paper diagram',objective:'Design an order model that avoids duplicated metrics and preserves historical meaning.',
    sections:[['Choose the grain before columns','A fact table records an event or snapshot at a declared grain: one row per order line, daily account balance, or shipment. Dimensions describe entities such as customer and product. A natural key comes from the source; a surrogate key is assigned by the model. Declare uniqueness and relationship expectations. An order-line fact needs a composite or surrogate key; order_id alone is not unique.'],['Normalize or make a star','Normalization reduces repeated operational attributes and update anomalies. A star puts measures in facts and descriptive attributes in dimensions for clear analytical joins. Snowflaking further separates dimension attributes, reducing duplication at the cost of more joins. It is not automatically superior. Additive measures can sum across dimensions; balances are often not additive across time, and ratios should be recalculated from numerators and denominators.'],['Preserve the past','Type 1 slowly changing dimensions overwrite attributes. Type 2 creates a new dimension version with valid_from and valid_to; facts join to the version effective at event time. Use non-overlapping intervals and one current version per natural key. An index accelerates certain lookups in some engines; partitioning separates data for pruning/manageability. Neither fixes an incorrect model, and warehouse engines have different physical design controls.']],language:'Model diagram',example:'fact_order_line: order_id + line_id, customer_key, product_key, ordered_at, quantity, line_amount\ndim_customer: customer_key, source_customer_id, city, valid_from, valid_to\ndim_product: product_key, source_product_id, category\nGrain: exactly one row per source order line.',task:'Sketch this star. Explain how a customer moving from Delhi to Pune should affect a historical city revenue report. State whether you need Type 1 or Type 2 and why.',rubric:['The fact key is unique at order-line grain.','A historical report uses event-time dimension versions if history is required.','Revenue is taken from line_amount rather than repeated order totals.'],solution:'Use Type 2 if reports must reflect the city at purchase time. End the old interval at the new version start, then join ordered_at >= valid_from AND ordered_at < valid_to (or an explicit current end convention). Use Type 1 if only the latest city is required and document that history changes.',mistake:'Joining every historical dimension version to every fact with only the natural key.',question:'Can daily account balances be summed across days as total cash?',options:['Yes, always','No; balances are snapshots and time aggregation needs a definition','Only with DISTINCT'],answer:1,feedback:'Summing snapshots counts the same balance repeatedly. Choose end-of-period or average balance as appropriate.',sources:[['Dimensional modeling','https://www.kimballgroup.com/data-warehouse-business-intelligence-resources/kimball-techniques/dimensional-modeling-techniques/']]
  },
  {
    id:6,title:'Cloud storage, identity, and boundaries',prerequisites:[1,2],environment:'Design exercise · optional cloud sandbox with billing controls',objective:'Explain equivalent cloud building blocks and design a least-privilege ingestion boundary.',sections:[['Map the building blocks','AWS S3, Azure ADLS Gen2, and Google Cloud Storage store objects addressed by container/bucket and key. They are not interchangeable local disks. Object prefixes organize data; formats matter: CSV is portable text, JSON handles nested records, and Parquet is columnar with typed fields and compression. Pick region based on residency, downstream location, and latency. Cross-region movement may incur charges.'],['Separate identity and network','IAM defines who may perform which actions on which resources. Prefer short-lived workload identities over copied long-lived keys. RBAC groups permissions by role; policies can restrict resources and conditions. A private network endpoint limits network reachability, but does not replace authorization. Encryption at rest and TLS in transit address different threats; key ownership and rotation need a policy.'],['Keep a safe landing zone','Use immutable raw object names with source/date/run identity. Record object checksum, schema version, and ingestion time in a manifest. Define retention and lifecycle rules to control cost without destroying replay inputs prematurely. A budget alert warns about spend; it is not necessarily a hard cap. Start with paper design and local files; create paid resources only when you choose a provider and understand cleanup.']],language:'Storage layout',example:'raw/orders/source=shop/date=2026-01-01/run=001/orders.json\nmanifest: {object_key, checksum, row_count, schema_version, loaded_at}\nrole ingestion: write raw/orders/*\nrole transform: read raw/orders/*, write curated/orders/*\nrole analyst: read curated/orders/*',task:'Map these roles to S3, ADLS, and GCS terminology. Draw the storage and network boundaries. Propose retention for raw and curated data and list all resources that would require cleanup in a paid lab.',rubric:['Analysts cannot write raw data or read unnecessary sensitive fields.','Region, encryption, identity, and retention choices are explicit.','No actual account credential appears in the design or repository.'],solution:'Use workload identity for ingestion, scoped object permissions, a selected region shared with processing, TLS, and a retention policy based on replay/privacy requirements. Record buckets/containers, compute, logs, and network resources in the cleanup checklist.',mistake:'Granting administrator rights because a narrowly scoped policy failed.',question:'Does a private endpoint replace IAM authorization?',options:['Yes','No, network access and permissions are separate controls','Only for Parquet files'],answer:1,feedback:'A reachable service must still authorize each identity and action.',sources:[['S3 overview','https://docs.aws.amazon.com/AmazonS3/latest/userguide/Welcome.html'],['ADLS overview','https://learn.microsoft.com/en-us/azure/storage/blobs/data-lake-storage-introduction'],['GCS overview','https://cloud.google.com/storage/docs/introduction']]
  },
  {
    id:7,title:'Warehouses: one workload, three platforms',prerequisites:[3,5,6],environment:'Browser SQL for concepts · optional Snowflake, BigQuery, or Databricks SQL account',objective:'Compare warehouse choices and optimize a workload using measured evidence.',sections:[['Separate storage from execution','A warehouse stores governed analytical data and executes queries with managed compute. Snowflake exposes virtual warehouses for compute; BigQuery has on-demand and capacity pricing models; Databricks SQL uses SQL warehouses with lakehouse tables. These are starting concepts, not identical features or pricing promises. Choose one platform for a practical lab rather than copying commands across all three.'],['Design for the workload','Column projection reduces unnecessary data. Date partitioning or clustering can help pruning when filters match the layout. Repeated tiny queries, giant scans, joins, concurrency, and dashboards have different cost/latency tradeoffs. Set query limits or timeouts and isolate experiments. Use native query profiles to inspect scanned data, shuffle, spill, and bottlenecks. A local DuckDB result cannot establish a cloud billing estimate.'],['Measure fairly','Compare the same result, data snapshot, compute configuration, and concurrency. Cache can make a second run seem dramatically faster; document warm/cold behavior. Record bytes/credits/compute time with provider units rather than claiming universal cost. A cheaper query returning the wrong rows is not an optimization.']],language:'DuckDB SQL · local plan only',example:'EXPLAIN SELECT customer_id, SUM(amount) AS revenue\nFROM orders\nWHERE order_date >= DATE \'2026-01-01\'\nGROUP BY customer_id;',task:'Inspect this plan in SQL Practice. Then write a provider comparison for a daily dashboard: data size, latency target, access controls, cost unit, and cleanup. If you have a sandbox, run one query and capture its native profile; otherwise label the comparison as a design exercise.',rubric:['The chosen platform has a workload-based justification.','Local plans and cloud measurements are clearly distinguished.','Cost claims name the unit and measurement conditions.'],solution:'For a daily dashboard, first consider batch ingestion and scheduled aggregation. Choose a provider based on existing cloud, governance, team skills, and measured economics. Apply a date filter, select necessary columns, and compare a native query profile before changing physical layout.',mistake:'Assuming adding an index or using the biggest compute always improves warehouse efficiency.',question:'What must remain equal in a performance comparison?',options:['Only query text','Result semantics, snapshot, and execution conditions','The platform logo'],answer:1,feedback:'A speed comparison is meaningful only when workload and correctness are comparable.',sources:[['Snowflake warehouses','https://docs.snowflake.com/en/user-guide/warehouses'],['BigQuery overview','https://cloud.google.com/bigquery/docs/introduction'],['Databricks SQL','https://docs.databricks.com/aws/en/sql/']]
  },
  {
    id:8,title:'Databricks, Delta, and experiment tracking',prerequisites:[5,7,9],environment:'Design here · code requires a Databricks workspace with Delta tables',objective:'Explain lakehouse layers, transactional table updates, and the role of MLflow.',sections:[['A notebook is an interface','Notebooks combine code, results, and explanation. Execution order and hidden state can make a notebook misleading. Move reusable transformations into tested functions and run from a clean session. Databricks combines managed compute, Spark, SQL, and governance. Workspace access, table permissions, and compute permissions are different boundaries.'],['Delta adds table semantics','Files alone do not provide reliable concurrent table updates. Delta Lake uses a transaction log to manage table versions and ACID changes. MERGE can apply updates/inserts using business keys, but the incoming source must first be unique at that key. Bronze retains source-like records, silver validates/deduplicates, and gold models business outputs. Layers are useful responsibility boundaries, not a requirement to duplicate every table three times.'],['History and MLflow','Table history/time travel helps debugging and reproducibility, but retention and vacuum policies limit availability; it is not an independent backup. MLflow tracks experiment parameters, metrics, and artifacts and supports model lifecycle workflows. For a data engineer, understand lineage from dataset version to experiment; model training is an extension, not required for every pipeline. Protect sensitive records in logged artifacts.']],language:'Delta SQL · external workspace',example:'MERGE INTO silver_orders AS target\nUSING unique_incoming_orders AS source\nON target.order_id = source.order_id\nWHEN MATCHED THEN UPDATE SET target.amount = source.amount\nWHEN NOT MATCHED THEN INSERT (order_id, amount)\nVALUES (source.order_id, source.amount);',task:'Design bronze, silver, and gold outputs for orders. State how duplicate updates are selected before MERGE. Describe what dataset version, parameters, and metric you would record for a demand-forecast experiment.',rubric:['Raw data remains replayable; silver defines key and timestamp precedence.','Gold has business grain and documented metrics.','MLflow logs distinguish parameters, metrics, artifacts, and input lineage.'],solution:'Deduplicate incoming orders using source updated_at plus a deterministic sequence. Bronze keeps source metadata, silver enforces schema/key rules, gold contains daily revenue at date grain. Log input table version, horizon parameter, validation error metric, and model artifact without customer PII.',mistake:'Treating Delta time travel as permanent backup or MERGE as automatic source deduplication.',question:'Why deduplicate the MERGE source?',options:['To prevent ambiguous multiple updates to the same target key','Because Delta cannot store strings','To erase source history'],answer:0,feedback:'The update rule must identify one intended source version for each target key.',sources:[['Delta documentation','https://docs.delta.io/latest/index.html'],['Databricks architecture','https://docs.databricks.com/aws/en/lakehouse/medallion'],['MLflow tracking','https://mlflow.org/docs/latest/ml/tracking/']]
  },
  {
    id:9,title:'ETL, ELT, and safe incremental loads',prerequisites:[2,3,5],environment:'Paper design + local Python thought experiment',objective:'Design rerunnable loads that handle updates, deletes, late arrivals, and schema changes.',sections:[['Place the transformation deliberately','ETL transforms before loading the analytical destination; ELT loads first then transforms there. Choose based on governance, engine capability, data volume, and replay requirements. Batch handles bounded intervals; streaming processes an unbounded sequence with state and checkpoints. A five-minute freshness requirement may be met by micro-batches without a continuously running stream.'],['Idempotency is a property','Applying the same input twice should produce the same logical result. Append-only insertion is unsafe when source events repeat. Use unique event keys, partition replacement, or key-based upserts. Watermarks/checkpoints record processed progress; save them after successful output publication. Select deterministic source intervals. For incremental updated_at loads, include overlap and choose the latest source version per key. Handle deletion tombstones explicitly.'],['Schema and replay','A new optional field may be compatible; renaming a required key or changing numeric values to free text may break consumers. Validate a schema contract, quarantine invalid rows, and coordinate breaking changes. Retain immutable raw inputs and transformation version for replay. Prefer atomic publication of complete outputs; otherwise readers can see half-written results.']],language:'Python',example:'events = [(1, 10), (2, 20), (1, 10)]\nstate = {}\nfor key, amount in events:\n    state[key] = amount\nassert sum(state.values()) == 30\nfor key, amount in events:  # replay\n    state[key] = amount\nassert sum(state.values()) == 30',task:'Extend the example to updates with version numbers and a deletion marker. Explain why taking the last arrival is wrong when versions arrive out of order. Design restart behavior when output succeeds but checkpoint storage fails.',rubric:['Latest source version wins regardless of arrival order.','Deletions remove or mark the logical record under an explicit policy.','Replay after checkpoint failure leaves the same logical result.'],solution:'Maintain key → (version, value/deleted). Apply only a higher version, with a documented tie rule. Publish output durably before checkpointing; on restart replay the interval through the idempotent write. Preserve tombstones long enough that old replays cannot resurrect deleted records.',mistake:'Using processing time as the source update order or advancing a checkpoint before output succeeds.',question:'What defines an idempotent load?',options:['It runs only once','Repeated identical input leaves the same logical output','It never uses checkpoints'],answer:1,feedback:'Retry safety depends on the result of replay, not preventing retries.',sources:[['Airflow concepts','https://airflow.apache.org/docs/apache-airflow/stable/core-concepts/overview.html'],['Kafka semantics','https://kafka.apache.org/documentation/#semantics']]
  },
  {
    id:10,title:'PySpark: schemas, shuffles, and skew',prerequisites:[4,9],environment:'Local PySpark with compatible Java/Python or managed Spark · browser does not run Spark',objective:'Read a distributed transformation plan and identify where work moves between machines.',sections:[['From DataFrame to job','Spark partitions a dataset so executors can process parts in parallel. DataFrame transformations such as select/filter are lazy; actions such as count/write trigger execution. Specify schemas for predictable types and validation. Spark SQL and DataFrame expressions share an optimized engine. Collect brings results to the driver: it is safe only for bounded small results.'],['Prefer native expressions','Use built-in functions for string, date, and conditional operations before Python UDFs. Native expressions expose more information to the optimizer; UDF boundaries can add overhead. Grouping and many joins cause a shuffle that moves records across partitions. A broadcast join may avoid a large shuffle when one side is small enough for executor memory. Do not force it without measuring.'],['Inspect distribution','Partition count controls task granularity; too few can underutilize workers, too many add overhead and small files. Skew means one partition has much more work, often from a hot key. Adaptive execution can adjust plans, but does not fix bad keys or unlimited data. Read explain, examine stage/task metrics, then test a targeted change. Partition by useful storage filters, not every high-cardinality user ID.']],language:'PySpark · external runtime',example:'from pyspark.sql import SparkSession, functions as F\nspark = SparkSession.builder.master("local[2]").appName("lesson").getOrCreate()\ndf = spark.createDataFrame([(1, 10.0), (1, 20.0), (2, 5.0)], "customer_id int, amount double")\nresult = df.groupBy("customer_id").agg(F.sum("amount").alias("revenue"))\nresult.explain()\nresult.orderBy("customer_id").show()\nspark.stop()',task:'Run in a compatible Spark environment. Expect customer 1 → 30 and customer 2 → 5. Explain why aggregation moves records. Replace one amount with null and state how the sum should behave and how missingness is monitored.',rubric:['You distinguish transformations from actions.','The plan identifies grouping/exchange and the result matches expected sums.','Nulls are counted separately from valid revenue.'],solution:'Rows with the same customer must meet in one aggregation group, usually requiring exchange across partitions. SUM ignores null inputs; this is a calculation rule, not permission to silently accept missing money. Track null count and enforce the business quality threshold.',mistake:'Calling collect on a huge dataset or using a Python UDF for a built-in operation.',question:'Which operation commonly requires a shuffle?',options:['Selecting two existing columns','Grouping by a key across partitions','Renaming a column'],answer:1,feedback:'Grouping must bring records for the same key together.',sources:[['PySpark quickstart','https://spark.apache.org/docs/latest/api/python/getting_started/quickstart_df.html'],['Spark tuning','https://spark.apache.org/docs/latest/sql-performance-tuning.html']]
  },
  {
    id:11,title:'Orchestration: dependencies, retries, backfills',prerequisites:[4,9],environment:'Design exercise · optional orchestrator deployment',objective:'Build a workflow contract with deterministic inputs and safe recovery.',sections:[['A scheduler coordinates work','Airflow expresses task dependencies in DAGs; Dagster emphasizes assets and their dependencies; Prefect represents Python flows and tasks. Each can schedule, observe, and retry work, but their deployment and state models differ. An orchestrator coordinates processing; it is not the warehouse or the transformation engine. Choose one to learn deeply.'],['Define a task contract','State input interval, expected output, and completion checks. Use a logical date/data interval rather than whatever happens to be latest. Tasks should tolerate retries and publish complete outputs. Persist large results in shared storage and pass small references, not giant datasets, between tasks. Store credentials through the chosen platform secret/connection mechanism.'],['Recover predictably','Retries handle transient faults; repeated data-contract failures should stop and alert. Backfill processes old intervals using the same transformation logic. Limit concurrent backfills so they do not starve current work. A dependency graph should prevent a dashboard publish after validation fails. Test local transform functions and failure paths before deploying the orchestration wrapper.']],language:'Workflow contract',example:'extract(interval) → raw manifest\nvalidate(manifest) → accepted/rejected counts\ntransform(interval) → staged daily revenue\nreconcile(interval) → pass/fail\npublish(interval) → atomic visible output\nFailure policy: retry transient extract failures; block publish on failed validation.',task:'Define a daily orders DAG. Simulate extract timing out, validation finding a missing key, and a requested seven-day backfill. State which tasks retry and which downstream tasks remain blocked.',rubric:['Each run has a fixed input interval.','Validation failure blocks publication.','Retries and backfill concurrency have finite limits.'],solution:'Retry extraction with bounded backoff. A bad key is a data failure: quarantine or stop according to contract, never blindly retry unchanged bad input. Backfill the seven intervals through the same idempotent tasks, with concurrency below the available capacity.',mistake:'Reading the latest file during a historical backfill and calling the result historical.',question:'Should publishing run after a failed reconciliation?',options:['Yes, because upstream extraction succeeded','No, the publication dependency should block it','Only on weekends'],answer:1,feedback:'A successful job is not enough; publication depends on validated output.',sources:[['Airflow best practices','https://airflow.apache.org/docs/apache-airflow/stable/best-practices.html'],['Dagster docs','https://docs.dagster.io/'],['Prefect docs','https://docs.prefect.io/']]
  },
  {
    id:12,title:'dbt: models, tests, documentation, incremental logic',prerequisites:[3,5,9],environment:'dbt project + chosen adapter/warehouse · browser example illustrates the logic',objective:'Organize SQL transformations into a tested dependency graph.',sections:[['Name the transformation layers','A source names an existing raw table. A staging model standardizes source names/types; intermediate models compose reusable logic; marts expose business grain. ref links models and creates dependency edges; source links declared sources. Views and tables have different freshness/storage/compute tradeoffs. Keep business definitions consistent across consumers.'],['Tests are queries with failure semantics','Built-in generic tests include unique, not_null, accepted_values, and relationships. A singular data test is SQL returning failing rows: zero rows means pass. Relationships ensure referenced keys exist, but do not prove all business logic. Document grain, columns, ownership, and assumptions; docs should explain meaning, not repeat the column name.'],['Incremental is a correctness problem','Incremental models process a subset rather than rebuilding everything. A unique_key and supported adapter strategy may update existing records, but late updates, source deletes, and schema changes still need explicit handling. Filter by source update time with overlap; deduplicate; test incremental output against a full rebuild on a small fixture. Rebuilding can be the better choice for a small table.']],language:'dbt model SQL · external project',example:'-- models/marts/customer_revenue.sql\nselect customer_id, sum(amount) as revenue\nfrom {{ ref(\'stg_orders\') }}\ngroup by customer_id\n\n-- tests/no_negative_revenue.sql\nselect * from {{ ref(\'customer_revenue\') }} where revenue < 0',task:'Design stg_orders and customer_revenue. Write a uniqueness test for customer_id and an explicit policy for refunds. Explain how an order updated yesterday but created last month reaches the incremental model.',rubric:['Model dependencies use ref/source rather than hardcoded deployment names.','Tests return bad rows and document allowable refunds.','Incremental filtering uses update semantics, not creation date alone.'],solution:'Use updated_at with overlap for changed records, deduplicate by order key/version, then recompute impacted customer aggregates or use an adapter-supported strategy that is correct at model grain. A revenue < 0 test is valid only if the business forbids negative net revenue; refunds may require a different test.',mistake:'Treating unique_key as a guarantee that incoming data is unique.',question:'A singular dbt data test returns five rows. What does that mean?',options:['Five passing records','Five failing records','The model was built five times'],answer:1,feedback:'A singular data test selects violations; no returned rows is success.',sources:[['dbt models','https://docs.getdbt.com/docs/build/models'],['dbt incremental models','https://docs.getdbt.com/docs/build/incremental-models'],['dbt tests','https://docs.getdbt.com/docs/build/data-tests']]
  },
  {
    id:13,title:'Data quality: contracts and reconciliation',prerequisites:[3,9,12],environment:'Browser SQL · optional dbt, Great Expectations, or Soda setup',objective:'Turn assumptions into checks with severity, ownership, and actionable failure handling.',sections:[['Choose dimensions of quality','Completeness checks required fields; uniqueness checks the declared key; validity checks ranges/formats; referential integrity checks relationships; freshness checks arrival delay; reconciliation compares source and destination counts/sums. Quality is contextual: a missing optional comment differs from a missing order key. Agree thresholds with consumers.'],['Express failing records','Start with SQL/dbt checks that return violations. Great Expectations expresses expectations and validation workflows; Soda expresses checks and scans. They can organize checks and reporting, but neither decides what correct revenue means. Choose one if operational needs justify it. Record checked population, rejected count, observed value, threshold, and owner.'],['Reject safely','Quarantine invalid records with reason and source identifier; protect sensitive fields and limit retention. A warning may allow publication, while a critical key failure blocks it. Reconcile accepted + rejected against ingested count to expose loss. Monitor unexpected drops and surges as well as null percentages; a perfectly valid but incomplete feed still breaks reporting.']],language:'DuckDB SQL · commerce',example:'SELECT customer_id, COUNT(*) AS occurrences\nFROM customers GROUP BY customer_id HAVING COUNT(*) > 1;\n\nSELECT o.order_id FROM orders o\nLEFT JOIN customers c USING (customer_id)\nWHERE c.customer_id IS NULL;',task:'Run both checks on commerce. Define critical versus warning checks for an orders feed. Given 100 source rows, 94 accepted, and 5 rejected, identify the missing reconciliation issue.',rubric:['Each check has a grain, threshold, severity, and owner.','Zero violations is distinguished from an empty source feed.','The 100 ≠ 94 + 5 difference triggers investigation.'],solution:'There is one unexplained missing row. Block publication if the contract demands exact reconciliation. Compare source IDs and load manifests, not just totals. Missing keys should normally be critical; a small optional-field null rate may be a warning if agreed with consumers.',mistake:'Calling a pipeline healthy because every quality query returned zero rows when the input itself was empty.',question:'Why reconcile accepted plus rejected counts?',options:['To make dashboards prettier','To detect silently lost records','To avoid defining keys'],answer:1,feedback:'Every input record needs a documented disposition.',sources:[['Great Expectations documentation','https://docs.greatexpectations.io/docs/'],['Soda documentation','https://docs.soda.io/'],['dbt testing','https://docs.getdbt.com/docs/build/data-tests']]
  },
  {
    id:14,title:'Observability: useful alerts and recovery',prerequisites:[11,13],environment:'Design exercise + local measurements',objective:'Distinguish healthy jobs from healthy data and write an actionable runbook.',sections:[['Measure what the consumer needs','Job duration measures processing time; end-to-end latency measures event-to-availability delay; freshness measures how recent the published data is. They are not interchangeable. Define an SLI, a measurable indicator; an SLO, the target; and any SLA, an agreement with consequences. For a daily dashboard, a successful 03:00 job can still publish yesterday’s incomplete data.'],['Create signals with context','Log run_id, source interval, input/output counts, rejects, timestamps, and output version. Avoid full sensitive records. Use metrics for trends and logs for diagnosis; lineage shows which consumers are affected. Alert on breaches requiring action rather than every harmless retry. Include owner, impact, last successful interval, and a runbook link.'],['Recover and learn','A runbook starts with confirming the signal and consumer impact, then checks source arrival, dependencies, permissions, schema, and recent changes. Restore validated data or replay fixed intervals. Communicate freshness/limitations to consumers. Record incident timeline, root cause, corrective action, and a test that catches recurrence.']],language:'Alert contract',example:'SLI: published_at - latest_source_event_at\nSLO: daily orders ready by 07:00 local reporting time\nAlert: current interval not published by deadline\nContext: run_id, interval, row_count, last_good_output\nRecovery: validate source → replay interval → reconcile → publish',task:'Write a runbook for a green pipeline whose output count drops 90%. Define who receives the alert, what evidence they inspect, and how they avoid publishing an incomplete correction.',rubric:['Data count/freshness signals supplement job status.','The runbook has an owner, confirmation steps, and a safe recovery path.','Replayed output is validated before becoming visible.'],solution:'Compare source manifest and prior comparable intervals; inspect source availability and filter/schema changes. If input is incomplete, wait/escalate rather than fill zeros. Restore last-good data with a freshness notice where appropriate. Replay the fixed interval and reconcile before publication.',mistake:'Alerting on every transient failure while ignoring a successful job with stale data.',question:'A job succeeded but the newest event is three days old. Is freshness proven?',options:['Yes','No, success and freshness are separate signals','Only if the job was fast'],answer:1,feedback:'The consumer cares about available data, not merely a successful process exit.',sources:[['Google SRE monitoring','https://sre.google/sre-book/monitoring-distributed-systems/']]
  },
  {
    id:15,title:'Security and governance throughout the pipeline',prerequisites:[6,13],environment:'Design exercise · synthetic data only',objective:'Define access, sensitive-data handling, lineage, retention, and auditable change.',sections:[['Classify before collecting','Identify PII and other sensitive fields, why they are needed, who may use them, and how long they should remain. Minimize data collection. Masking hides selected values at access time; hashing is not necessarily anonymization, especially for guessable identifiers. Separate public aggregate data from restricted detailed records. Use synthetic records in lessons and demos.'],['Layer the controls','Least privilege scopes identities to actions/resources. RBAC simplifies assignment, while row/column policies may constrain what data a role sees. Encrypt traffic and storage; manage keys and rotate credentials. Keep secrets in a supported secret store, not notebooks, logs, or Git. Separate development and production environments and review changes before production publication.'],['Make governance operable','A catalog records owner, description, grain, sensitivity, and lineage. Audit logs record who accessed or changed protected resources; protect and retain the logs appropriately. Retention/deletion must cover copies, derived tables, raw replay files, and backups according to your actual policies and obligations. Governance is a maintained process rather than one checkbox.']],language:'Access matrix',example:'ingestion service: source read + raw write\ntransform service: raw read + curated write\nanalyst: approved curated read, restricted columns masked\nadmin: controlled elevated access with audit trail\nall roles: no secrets in source control',task:'For customer email, order amount, and region, classify fields and design analyst/service access. Draw lineage from raw customer to dashboard. Explain how deleting a customer affects raw retention and replay.',rubric:['Every sensitive field has purpose, owner, access, and retention policy.','Service privileges are limited and audited.','Deletion/replay interactions are considered rather than assuming one table deletion is enough.'],solution:'Restrict emails and expose aggregates where sufficient. Retain only data justified by policy; apply deletion rules to downstream copies and ensure replay cannot recreate removed data. Consult the organization’s policy/legal owner for real obligations; this exercise specifies controls, not legal compliance.',mistake:'Publishing hashed emails as anonymous data or committing an access token in a notebook.',question:'Does hashing a predictable email prove anonymity?',options:['Yes, always','No, it may remain linkable or guessable','Only if it is uppercase'],answer:1,feedback:'Pseudonymization may reduce exposure but does not automatically remove identification risk.',sources:[['NIST privacy framework','https://www.nist.gov/privacy-framework'],['OWASP secrets management','https://cheatsheetseries.owasp.org/cheatsheets/Secrets_Management_Cheat_Sheet.html']]
  },
  {
    id:16,title:'Project A: a rerunnable batch pipeline',prerequisites:[4,5,9,11,13,15],environment:'Local Python + SQLite · optional cloud warehouse extension',objective:'Deliver raw ingestion → validated storage → daily revenue report with reproducible tests.',sections:[['Build a small end-to-end slice','Use synthetic orders with order_id, updated_at, ordered_date, amount, and status. Create raw, quarantine, and published outputs. Ingest a CSV, validate required keys/types, deduplicate by source version, and load a keyed SQLite table. SQLite is a local practice destination; document what changes for a cloud warehouse. The report should show paid daily revenue and accepted/rejected counts.'],['Make correctness observable','Create fixtures containing duplicate IDs, a late update, malformed amount, and cancelled orders. Preserve the source file and record its checksum and row count. Load inside a transaction so partial failures do not publish half a result. Upsert current records by key/version, then recompute daily totals from current state. Include a deletion policy if sources delete records.'],['Publish and prove','Export a daily revenue CSV and chart/table. Compare source reconciliation, run the pipeline twice, and assert identical logical output. Inject failure before publication and prove last-good output remains available. Document assumptions, commands, expected values, dependency versions, and limitations. A working local pipeline is useful evidence; it is not a claim of cloud deployment.']],language:'Project fixture',example:'order_id,updated_at,ordered_date,amount,status\n1,2026-01-01T10:00:00Z,2026-01-01,100,paid\n2,2026-01-01T11:00:00Z,2026-01-01,50,cancelled\n1,2026-01-02T09:00:00Z,2026-01-01,120,paid\n3,2026-01-02T10:00:00Z,2026-01-02,80,paid',task:'Create the local pipeline described above. Start with this fixture; then add one malformed amount row to quarantine. Capture the report, tests, and second-run comparison in your portfolio notes.',rubric:['Current logical state has three orders; paid revenue is Jan 1 = 120, Jan 2 = 80.','The malformed row is quarantined with a reason and counts reconcile.','Replay produces the same output; failure does not publish partial data.','A README lets another person reproduce the result.'],solution:'Stage/validate records, select the latest updated_at per order_id, upsert using a version guard, and calculate SUM(amount) WHERE status = paid GROUP BY ordered_date. Use a transaction and write a temporary report before atomic replacement. Compare sorted output/checksums across runs.',mistake:'Appending daily revenue every run or deduplicating with arbitrary first arrival.',question:'The corrected amount for order 1 is 120. What is Jan 1 paid revenue?',options:['220','120','170'],answer:1,feedback:'An update replaces the logical order value; it is not an additional purchase.',sources:[['Python sqlite3','https://docs.python.org/3/library/sqlite3.html'],['SQLite upsert','https://www.sqlite.org/lang_UPSERT.html']]
  },
  {
    id:17,title:'Project B: near-real-time ingestion and replay',prerequisites:[8,9,10,14,15,16],environment:'Local event simulation first · Kafka/Kinesis → Databricks requires external infrastructure',objective:'Demonstrate deduplication, late-event handling, checkpoint recovery, and measured latency.',sections:[['Model the stream','Events have event_id, entity_id, event_time, source_version, and payload. Event time is when something happened; processing time is when your pipeline handles it. Kafka topics have ordered partitions, with ordering within a partition, not globally. Kinesis streams also partition records through shard/partition-key mechanisms. Keys affect ordering and hot partitions. Select one broker for deployment.'],['State the delivery contract','At-least-once delivery permits repeats. Deduplicate with event IDs and keep sufficient state for the replay window. Checkpoints track progress; sinks must cooperate with replay semantics. A claim of exactly-once needs a specific source/engine/sink configuration and boundaries, not a slogan. Watermarks bound how long state waits for late event-time records; decide what happens to later events.'],['Build in two stages','First replay a local fixture with duplicates and delayed events, measuring logical outputs. Then, if you have a sandbox, produce into Kafka or Kinesis, consume with an appropriate Spark connector, and publish Delta silver/gold tables. Record end-to-end delay and restart from checkpoint after intentional interruption. A local simulator validates logic, not cloud throughput, production durability, or connector installation.']],language:'Event fixture',example:'event_id,key,event_time,arrival_time,amount\ne1,1,10:00,10:00,20\ne2,1,10:01,10:01,30\ne1,1,10:00,10:02,20\ne3,2,09:59,10:03,10\nUnique-event total: 60; raw arrival total: 80.',task:'Simulate the fixture in Python; deduplicate by event_id and calculate totals by event-time minute. Restart halfway with saved state. Write a late-event policy and a Kafka/Kinesis → bronze → silver → gold architecture. If deployed, record connector/runtime versions and measured latency.',rubric:['Replay produces total 60, not 80.','Event-time windows and late-event policy are explicit.','Checkpoint recovery does not lose or double-count records.','Simulation results are labeled separately from external deployment evidence.'],solution:'Persist seen event IDs and aggregated state consistently with the consumed offset/checkpoint; replay safely after interruption. For a bounded fixture, keep all seen IDs. For an unbounded stream, define retention/watermark bounds and route too-late events to correction/reconciliation. Partition by a key suited to ordering and load.',mistake:'Assuming global ordering or claiming exactly-once because a checkpoint exists.',question:'What does at-least-once delivery require you to handle?',options:['Only missing events','Duplicate delivery','No retries'],answer:1,feedback:'A successfully processed event may be delivered again, so logical writes need replay safety.',sources:[['Kafka introduction','https://kafka.apache.org/intro'],['Kinesis concepts','https://docs.aws.amazon.com/streams/latest/dev/key-concepts.html'],['Spark structured streaming','https://spark.apache.org/docs/latest/streaming/index.html']]
  },
  {
    id:18,title:'Project C: reliability and measured optimization',prerequisites:[13,14,16,17],environment:'Local pipeline from Project A · optional native cloud metrics',objective:'Improve a working pipeline with quality gates, incident recovery, and an honest before/after comparison.',sections:[['Extend an existing system','Use Project A instead of inventing another dataset. Add key/null/reconciliation checks, run metadata, freshness deadline, and failure alerts. Record a baseline on a fixed fixture: runtime, input rows, output counts, and memory or native billed unit if available. Define the consumer impact of failure before writing alerts.'],['Inject failures deliberately','Test an absent input, duplicate/update burst, unexpected schema, and interrupted publication. Each should have a documented outcome: retry, quarantine, block, or restore. Verify that a runbook can recover the correct interval. A data-quality threshold must reflect the business contract, not be tuned merely to pass.'],['Optimize one bottleneck','Use a profiler or query plan to identify unnecessary reads, repeated transformations, or a poor join. Change one factor and compare equal outputs under comparable conditions. Local elapsed time is not cloud cost; do not invent savings percentages. Keep the original baseline, test data size, cache conditions, and repetitions so a reviewer can evaluate the result.']],language:'Experiment record',example:'snapshot: fixture-v2; rows: measured\nbaseline: median of 5 comparable runs\nchange: remove repeated full-file parsing\ncorrectness: identical sorted report + reconciliation\nresult: measured runtime, range, environment\nlimitations: local test; no cloud billing claim',task:'Add two critical checks, a freshness signal, and a recovery runbook to Project A. Inject three failures. Measure one optimization and write a before/after note with evidence.',rubric:['Bad data prevents unvalidated publication.','Failure recovery restores a reconciled output.','The performance comparison uses identical semantics and disclosed conditions.','No invented cost/latency claims appear.'],solution:'Check unique current keys and source disposition counts, log latest published interval, and block publication on critical violations. Recover using raw replay plus idempotent writes. Compare several baseline/changed runs with equal fixture and outputs; report actual values and variability.',mistake:'Comparing different datasets or warm cache against cold cache and calling the difference an optimization.',question:'A faster query drops 10% of required records. Is it an improvement?',options:['Yes, faster is better','No, correctness is part of the acceptance criteria','Only if cost is lower'],answer:1,feedback:'Performance is evaluated only after equivalent correct output is established.',sources:[['SRE handling overload','https://sre.google/sre-book/handling-overload/'],['DuckDB profiling','https://duckdb.org/docs/stable/dev/profiling.html']]
  },
  {
    id:19,title:'Portfolio documentation people can reproduce',prerequisites:[16],environment:'Local Git repository + diagram editor or paper',objective:'Turn a project into verifiable evidence with commands, architecture, results, and limitations.',sections:[['Write for a stranger','A README should answer: what problem, what input, what grain, how to run, what output, how to test, and what is not demonstrated. Give prerequisites and tested versions, setup commands, a tiny synthetic fixture, and expected values. Add troubleshooting for likely environment errors. Never include live secrets or private customer records.'],['Draw responsibility boundaries','Show source → raw → validation → transformation → storage → consumer. Label data formats, keys, intervals, checkpoints, and trust boundaries. A diagram should explain failure/replay paths and why a component exists. Avoid decorating it with services you did not use. Track ownership and lineage alongside the graph.'],['Results need a method','Record baseline, conditions, measurements, and limitations. Screenshots are supporting evidence; runnable checks are stronger. Include a failure injection and recovery record, cleanup instructions, and known tradeoffs. A local demonstration can show engineering reasoning without pretending it handled millions of production rows.']],language:'README outline',example:'# Problem and consumer\n## Dataset and grain\n## Architecture and trust boundaries\n## Tested environment and setup\n## Run with sample fixture\n## Expected output and tests\n## Failure/replay demonstration\n## Measurements and limitations\n## Cleanup and next steps',task:'Write this README for Project A. Ask a fresh reader—or your future self in a new directory—to follow only the commands. Record and fix every missing step.',rubric:['Commands reproduce expected values from synthetic inputs.','Diagram matches the implemented components.','Measurements include method; limits and cleanup are visible.'],solution:'Include the exact interpreter/environment command, fixture location, run command, and assertions for Jan 1 = 120 and Jan 2 = 80. Document how to inject malformed input and replay. Link code/tests from the results page and distinguish implemented work from proposed cloud extension.',mistake:'A beautiful architecture diagram that includes components absent from the repository.',question:'What is the strongest portfolio evidence here?',options:['A claim of production scale','Reproducible code, fixture, expected output, and checks','A large list of technology logos'],answer:1,feedback:'Reviewers can verify working behavior and understand the limits.',sources:[['GitHub READMEs','https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-readmes']]
  },
  {
    id:20,title:'System design: explain the tradeoffs',prerequisites:[5,6,9,11,14,15],environment:'Paper diagram + timed explanation',objective:'Give a structured ten-minute design with requirements, failure recovery, cost, and security.',sections:[['Clarify the problem first','Ask who consumes the data, required freshness, data volume/rate, retention, update/delete semantics, and acceptable loss/downtime. State assumptions when answers are unavailable. Estimate peak as well as average load using units. Do not jump to Kafka because the question says scale; latency and operational constraints determine whether batch is enough.'],['Trace one record end to end','Show ingestion, durable landing, validation, transformation, modeled storage, and serving. Explain key/grain, partition strategy, checkpoints, idempotency, schema contracts, and observability. Discuss what happens on source outage, consumer outage, poison event, duplicate, late update, and credential failure.'],['Make a decision and its limits','Compare one credible alternative. A simple batch design may reduce operational burden but misses a seconds-level requirement. Streaming may reduce latency with higher state/recovery complexity. Address access, sensitive fields, deletion, replay retention, and cost units. End with the highest-risk assumption and how you would validate it.']],language:'Ten-minute structure',example:'0–2 min: requirements, assumptions, load estimate\n2–5 min: diagram and one-record walkthrough\n5–7 min: keys, replay, failure recovery\n7–9 min: security, cost, alternative tradeoff\n9–10 min: risks and validation plan',task:'Design orders analytics for 1 million events/day with a five-minute dashboard freshness target. Estimate average events/second, account for peaks, and compare five-minute micro-batch with streaming. Explain duplicate recovery.',rubric:['Average ≈ 11.6 events/second; peak is a stated assumption, not confused with average.','Design satisfies freshness including ingestion and publication time.','Replay, access, late events, monitoring, and cost are covered.'],solution:'1,000,000 / 86,400 ≈ 11.6/s average. Test peak factor and event size. A five-minute schedule alone can exceed five-minute freshness once processing is included; use a shorter interval or streaming if justified. Durable raw landing, stable keys, idempotent writes, and atomic publication enable recovery.',mistake:'Ignoring processing time when claiming a five-minute scheduled job meets a five-minute end-to-end target.',question:'Does a five-minute schedule guarantee five-minute freshness?',options:['Yes','No, ingestion and processing delays also count','Only for JSON'],answer:1,feedback:'Freshness is end to end, including waiting and execution.',sources:[['AWS reliability pillar','https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/welcome.html']]
  },
  {
    id:21,title:'Five hard SQL interview patterns',prerequisites:[3,5],environment:'Browser SQL + existing Interview Mode',objective:'Solve and explain top-N, deduplication, gaps/islands, retention, and period comparisons.',sections:[['Top-N and latest record','For top-N per group, choose ROW_NUMBER for exactly N deterministic rows, or rank functions when ties should remain. Deduplication needs a stable key and ordering by source version/time plus a tie-breaker. Clarify whether a latest record that is deleted should disappear rather than falling back to an older live record.'],['Gaps and islands','Consecutive activity dates form islands. After removing duplicate days, compute ROW_NUMBER per entity and subtract that sequence from the date to get a grouping key in dialects supporting the operation. Alternatively use LAG to mark a new island when the gap exceeds one day and a cumulative sum to assign island IDs. Specify timezone and what consecutive means.'],['Retention and period comparison','Assign each customer to one cohort, identify qualifying activity, then count distinct customers per cohort/period against the fixed cohort denominator. Missing months need a calendar spine when calendar comparisons matter. LAG compares the previous row; for growth guard division by zero and explain missing prior periods. Always state grain and validate with a tiny fixture before optimizing.']],language:'DuckDB SQL · commerce',example:'WITH ranked AS (\n SELECT customer_id, order_id, order_date, amount,\n ROW_NUMBER() OVER (PARTITION BY customer_id\n ORDER BY order_date DESC, order_id DESC) AS rn\n FROM orders\n)\nSELECT customer_id, order_id, amount FROM ranked WHERE rn = 1;',task:'Run the latest-order example. Modify it for top two orders per customer. Then explain a fixture with two orders on the same date, missing months, and duplicate activity events. Open Interview Mode for the existing timed SQL questions.',rubric:['Tie behavior is explicit.','Cohort denominator and activity event are defined.','Period comparisons distinguish previous observed row from previous calendar month.'],solution:'Use rn <= 2 for exactly two orders, with deterministic order_id ties. For retention, deduplicate customer/activity-period before counting and preserve cohort size. Build missing calendar periods if the metric is calendar-month growth; guard the prior denominator with NULLIF.',mistake:'Claiming LAG always means last calendar month or counting events instead of retained customers.',question:'What does LAG(revenue) ordered by month return if February is missing?',options:['Always February revenue','The previous observed row, potentially January','Zero automatically'],answer:1,feedback:'A window follows rows. A calendar spine is needed to represent missing periods explicitly.',sources:[['DuckDB windows','https://duckdb.org/docs/stable/sql/functions/window_functions.html']]
  },
  {
    id:22,title:'Behavioral interviews with honest evidence',prerequisites:[16,18],environment:'Writing + optional voice recording',objective:'Explain a real or practice project with clear ownership, evidence, and reflection.',sections:[['Use a truthful story','Choose a project you actually built. If it was a practice exercise, say so. Situation provides context; task identifies your responsibility; action explains decisions you personally made; result gives observed evidence. A result can be correctness/recovery proof rather than a fabricated business impact. Separate your actions from team actions.'],['Show reasoning under difficulty','For a bad metric, explain the symptom, consumer impact, hypothesis, investigation, root cause, fix, and prevention. Describe row multiplication or missed updates concretely. For a failure, explain what you learned and changed rather than blaming a tool or teammate. Interviewers may ask how you know the fix worked.'],['Make it concise and adaptable','Prepare a two-minute version and deeper technical follow-ups. A STAR structure is a guide, not a script to recite. Include tradeoffs and what you would improve. Avoid private customer details, employer secrets, and invented savings.']],language:'Story outline',example:'Situation: practice orders pipeline double-counted replayed inputs.\nTask: make repeated runs safe.\nAction: declared key/version, added guarded upsert and replay test.\nResult: both runs produced Jan 1 = 120 and Jan 2 = 80.\nReflection: next test deletes and late updates.',task:'Write two stories: a pipeline you built and a metric you corrected. Mark practice work honestly. Rehearse a two-minute answer, then explain exactly how the result was verified.',rubric:['Ownership and context are accurate.','Actions explain reasoning rather than only tools.','Results cite actual checks/measurements and include reflection.'],solution:'Use Project A and the order-total duplication scenario if those are your completed exercises. Say “in my practice project” and show fixture/test evidence. If you have not performed the correction yet, perform it first rather than presenting it as completed work.',mistake:'Claiming professional production experience or financial savings from a local exercise.',question:'Can a practice project be a valid behavioral example?',options:['No','Yes, if its context and evidence are honestly described','Only if renamed as client work'],answer:1,feedback:'A truthful example can demonstrate your reasoning and learning.',sources:[['STAR guidance','https://nationalcareers.service.gov.uk/careers-advice/interview-advice/the-star-method']]
  },
  {
    id:23,title:'Resume and LinkedIn: claims you can defend',prerequisites:[19,22],environment:'Local document · no publication required',objective:'Translate completed projects into accurate, specific evidence for an intended role.',sections:[['Choose a target','Read a few target job descriptions and distinguish must-have skills from optional technologies. Prioritize relevant demonstrated work. Separate employment, education, and personal projects. Course completion is not years of experience or a professional certification. Link a reproducible portfolio rather than listing every service you have read about.'],['Write concrete bullets','Use action + system + evidence. “Built a local idempotent orders pipeline with keyed upserts and replay assertions” is stronger than “expert in modern data stack.” Include rows, runtime, latency, or cost only when measured, and identify fixture/local/cloud conditions. A metric needs a baseline and measurement method to support a percentage improvement.'],['Keep profiles consistent','Resume and LinkedIn dates, titles, project scope, and skills should agree. Describe the problem, implementation, validation, and limitations in a project entry. Remove secrets and private data from linked work. Tailor emphasis to the role without inventing achievements or impersonating employment.']],language:'Example bullet',example:'Built a local Python/SQLite orders pipeline with version-based upserts,\nquarantine records, and replay tests; reproduced daily revenue from\na documented synthetic fixture.\nOptional measured extension: add your actual row count/runtime and test conditions.',task:'Draft three bullets for completed projects. Under each, write the evidence link or measurement that supports it. Remove any technology not actually used and any number you cannot reproduce.',rubric:['Each statement has evidence and honest context.','Metrics identify the tested workload and environment.','Personal projects are distinct from employment.'],solution:'Use the README/test output for a correctness bullet, a failure-injection record for reliability, and your controlled before/after experiment for performance. If no performance measurement exists, describe the capability without a fabricated percentage.',mistake:'Converting a course plan into a list of mastered technologies before doing the labs.',question:'When should you claim a 40% cost reduction?',options:['When the architecture looks cheaper','When comparable measured billing evidence supports it','Whenever a query runs faster locally'],answer:1,feedback:'A cost claim needs actual comparable cost evidence, not an inferred runtime change.',sources:[['Resume guidance','https://nationalcareers.service.gov.uk/careers-advice/cv-sections']]
  },
  {
    id:24,title:'Mock interviews: feedback and deliberate retry',prerequisites:[20,21,22,23],environment:'Timer + notes · recording optional and local',objective:'Practice a complete interview, identify specific weaknesses, and improve them with evidence.',sections:[['Structure a realistic session','Use 15 minutes for SQL, 10 for system design, 5 for a behavioral answer, and 5 for review. Work without looking at solutions. Clarify assumptions aloud, explain your grain, and test edge cases. Recording can expose unclear explanation, but a written observer/timer log is sufficient; no upload is required.'],['Score observable behavior','For SQL assess correctness, grain/ties/nulls, edge-case testing, and explanation. For design assess requirements, coherent flow, recovery, security/cost, and tradeoffs. For behavioral assess ownership, reasoning, evidence, and reflection. Score each dimension 0 absent, 1 partial, 2 clear. Scores are self/peer feedback rather than an employment guarantee.'],['Redo one weakness','Select the lowest dimension, perform a focused exercise, and attempt a different but related question. Repeating a memorized answer can raise fluency without improving transfer. Preserve your first attempt and notes so improvement is visible. Stop when evidence improves, not merely when the answer sounds confident.']],language:'Review log',example:'date | prompt | dimension | score 0–2 | evidence | next drill\nExample: SQL latest record | tie handling | 0 | no stable tie key | add duplicate timestamp fixture\nRetry: top-N per group | tie handling | 2 | explained ROW_NUMBER vs RANK',task:'Run one mock using an existing SQL interview question, the million-events design prompt, and a Project A story. Score each dimension, choose two weaknesses, and perform a second session with new prompts.',rubric:['The first attempt and score evidence are retained.','Remediation drills target an observed weakness.','The second attempt uses new prompts and shows specific improvement.'],solution:'If grain is weak, draw input/output grain and test a duplicate fixture before the retry. If recovery is weak, interrupt a local load and explain checkpoint/output ordering. Compare the same rubric dimensions across sessions and record unresolved gaps honestly.',mistake:'Counting repeated memorized answers as proof you can solve new problems.',question:'What is the best next action after a mock?',options:['Memorize the exact answer','Drill an observed weakness and retry a related new prompt','Add every tool to your resume'],answer:1,feedback:'Deliberate practice changes a specific capability and tests transfer.',sources:[['Interview preparation','https://nationalcareers.service.gov.uk/careers-advice/interview-advice']]
  }
];

export type LearningProgress = { lessons: number[]; quizzes: number[]; labs: number[]; notes: Record<string,string> };
export const emptyProgress: LearningProgress = {lessons:[], quizzes:[], labs:[], notes:{}};
export function normalizeProgress(value: unknown): LearningProgress {
  const data = value && typeof value === 'object' ? value as Partial<LearningProgress> : {};
  const ids = (input: unknown, max: number) => Array.isArray(input) ? [...new Set(input.filter((id): id is number => Number.isInteger(id) && id > 0 && id <= max))] : [];
  const notes: Record<string,string> = {};
  if(data.notes && typeof data.notes === 'object' && !Array.isArray(data.notes)) for(const [key,value] of Object.entries(data.notes)) if(topics.some(t=>String(t.id)===key) && typeof value === 'string') notes[key] = value.slice(0,12000);
  return {lessons:ids(data.lessons,32),quizzes:ids(data.quizzes,24),labs:ids(data.labs,24),notes};
}
